/* Mind-sage Version 3 | GitHub Pages frontend | No third-party JS. */
'use strict';
const V3_STORE_KEY='mindsage_v4_personal_on_device';
const V3_PREF_KEY='mindsage_v4_preferences';
const V3_DATA_DEFAULT=()=>({garden:[],journal:[],plan:null,journeys:[],landscape:[]});
let v3Data=V3_DATA_DEFAULT();
let v3Loaded=false;
let v3Scene='sunrise',v3Story=null,v3Sound=null,v3Audio=null,v3DeferredInstall=null,v3AIHistory=[];
let v3Prefs={font:'normal',contrast:false,motion:false};
try{const raw=JSON.parse(localStorage.getItem(V3_PREF_KEY)||'{}');if(raw&&typeof raw==='object')v3Prefs={...v3Prefs,...raw};}catch(_){}
function v3Load(){if(!adult()||v3Loaded)return;v3Loaded=true;try{const d=JSON.parse(localStorage.getItem(V3_STORE_KEY)||'null');if(d&&typeof d==='object')v3Data={...V3_DATA_DEFAULT(),...d};}catch(_){} }
function v3Save(){if(!adult())return;try{localStorage.setItem(V3_STORE_KEY,JSON.stringify(v3Data));}catch(_){alert(T('Storage is not available on this device. This change will last for this session.','এই ডিভাইসে তথ্য সংরক্ষণ করা যাচ্ছে না। সেশনে থাকবে।'));}}
function v3Today(){return new Date().toLocaleDateString('en-CA',{timeZone:'Asia/Kolkata'});}
function v3PrivateNote(){return T(adult()?'Saved only in this browser on this device. Other people using this browser may see entries.':'Under-18 entries stay in this page session and are not saved across reloads.','প্রাপ্তবয়স্কদের তথ্য শুধু এই ব্রাউজারে থাকে; অপ্রাপ্তবয়স্কদের তথ্য শুধু এই সেশনে থাকে।');}
function v3FocusLabel(x){return ({worry:T('Steadying worry','দুশ্চিন্তা কমানো'),rest:T('Rest and sleep','বিশ্রাম ও ঘুম'),study:T('Study balance','পড়াশোনার ভারসাম্য'),connection:T('Connection','সম্পর্ক ও সহায়তা'),hope:T('Energy and hope','শক্তি ও আশা')})[x]||'';}
function v3Banner(label,title,subtitle){return `<div class="v3-pagehead"><div><span class="v3-kicker">${label}</span><h1>${title}</h1><p>${subtitle}</p></div><span class="v3-heading-mark" aria-hidden="true">✳</span></div>`;}
function v3Tiles(){const cards=[['landscape','☀','Emotion Landscape','অনুভূতির আকাশ','Name how today feels and find a gentle next step.','আজ কেমন লাগছে বলুন, পরের ছোট পদক্ষেপ নিন।','mint'],['garden','❀','Mind Garden','মনের বাগান','See a garden grow as you notice your self-care.','নিজের যত্নে মনের বাগান গড়ুন।','apricot'],['journey','✧','Life Journey','জীবনের সফর','Choose your path through realistic student situations.','জীবনের পরিস্থিতি নিয়ে গল্পে অংশ নিন।','lavender'],['plan','◷','Personal Plan','নিজস্ব পরিকল্পনা','Build a 7-day or 14-day routine at your own pace.','নিজের গতিতে ৭ বা ১৪ দিনের পরিকল্পনা।','sky'],['journal','✎','Mind Journal','মনের জার্নাল','Write a private note, feeling, or gratitude.','নিজের অনুভূতি বা কৃতজ্ঞতা লিখুন।','rose'],['insights','◈','My Insights','আমার পর্যবেক্ষণ','Notice patterns without labels or judgments.','নিজের পরিবর্তন বুঝুন, বিচার নয়।','mint']];return cards.map(([p,s,en,bn,desc,descBn,tone])=>`<a class="v3-feature ${tone}" href="#/${p}"><span class="v3-feature-icon">${s}</span><span class="v3-feature-bottom"><strong>${T(en,bn)}</strong><small>${T(desc,descBn)}</small></span><span class="v3-feature-arrow">↗</span></a>`).join('');}
function v3Landing(){return shell(`<div class="v3-home"><div class="v3-hero"><div class="v3-hero-copy"><span class="v3-hero-label">✦ ${T('MIND-SAGE · VERSION 3','মাইন্ড-সেজ · সংস্করণ ৩')}</span><h1>${T('Your mind deserves<br><em>room to bloom.</em>','আপনার মন পেতে পারে<br><em>প্রস্ফুটিত হওয়ার অবকাশ।</em>')}</h1><p>${T('A thoughtful place for students to check in, build peaceful routines, explore real-life choices, and find support. One step at a time.','নিজের অনুভূতি বোঝা, সহজ অভ্যাস তৈরি, জীবনের গল্পে অংশ নেওয়া এবং সহায়তা পাওয়ার একটি শান্ত স্থান।')}</p><div class="v3-hero-actions"><a class="v3-main-button" href="#/${state.level?'dashboard':'landscape'}">${T(state.level?'Open my space':'Explore my wellbeing space',state.level?'আমার স্থান খুলুন':'আমার সুস্থতার স্থান')} <span>↗</span></a><a class="v3-ghost-button" href="#/bromind">${T('Bro-minD Plus','ব্রো-মিন্ড প্লাস')} ${I('arrow',16)}</a></div><div class="v3-hero-trust">${I('shield',17)} ${T('Private-first · No account required · Optional offline access','গোপনীয়তা প্রথমে · অ্যাকাউন্ট ছাড়াই · অফলাইনে ব্যবহার')}</div></div><div class="v3-hero-illustration" aria-hidden="true"><div class="v3-orbit orbit-one"></div><div class="v3-orbit orbit-two"></div><div class="v3-hero-sun"></div><div class="v3-hero-ground"></div><div class="v3-hero-vase"></div><div class="v3-hero-stem"></div><div class="v3-hero-flower"><span>✿</span></div><div class="v3-hero-floating float-a">a gentle moment</div><div class="v3-hero-floating float-b">small steps, real care</div><div class="v3-hero-star">✳</div></div></div>
 <div class="v3-trustbar"><span>✧ ${T('For every student journey','প্রতিটি শিক্ষার্থীর জন্য')}</span><span>◉ ${T('Personal, private reflections','ব্যক্তিগত অনুভূতি')}</span><span>✿ ${T('A calmer daily routine','সহজ দৈনন্দিন যত্ন')}</span></div>
 <section class="v3-section"><div class="v3-sectionhead"><div><span class="v3-kicker">${T('EXPLORE YOUR SPACE','আপনার স্থান খুঁজুন')}</span><h2>${T('Wellbeing can take many forms.','ভালো থাকার অনেক পথ আছে।')}</h2></div><p>${T('Six ways to begin, with no pressure to do everything.','শুরু করার ছয়টি পথ, সবকিছু একসঙ্গে করতে হবে না।')}</p></div><div class="v3-featuregrid">${v3Tiles()}</div></section>
 <section class="v3-section v3-education"><div class="v3-sectionhead"><div><span class="v3-kicker">${T('START WITH YOUR STUDENT STAGE','শিক্ষার পর্যায় বেছে নিন')}</span><h2>${T('A space for the journey you are in.','আপনার শিক্ষাজীবনের জন্য একটি স্থান।')}</h2></div><p>${T('Choose a category to begin the original assessment and personal dashboard.','আপনার বিভাগের মাধ্যমে ব্যক্তিগত ড্যাশবোর্ড ও মূল্যায়ন শুরু করুন।')}</p></div>${categoryCards()}</section>
 <section class="v3-editorial"><div class="v3-editorial-icon">✿</div><div><span class="v3-kicker">${T('A NOTE TO YOURSELF','নিজের জন্য একটি কথা')}</span><h2>${T('You are allowed to grow gently.','ধীরে ধীরে এগোনোরও মূল্য আছে।')}</h2><p>${T('You do not need to turn every difficult day into a success story. Sometimes, noticing how you feel and choosing one caring action is enough for today.','প্রতিটি কঠিন দিনকে সাফল্যের গল্প করতে হবে না। কখনো নিজের অনুভূতি বোঝা এবং একটি ছোট যত্নের কাজই যথেষ্ট।')}</p></div><a href="#/journal" class="v3-editorial-link">${T('Open Mind Journal','জার্নাল খুলুন')} ↗</a></section></div>`);}
function v3Dashboard(){if(!state.level)return v3Landing();const mostRecent=v3Data.landscape.slice(-1)[0];const todayDone=v3Data.garden.filter(x=>x.date===v3Today()).length;
 const extra=`<section class="v3-section v3-dash-addition"><div class="v3-sectionhead"><div><span class="v3-kicker">MIND-SAGE V3</span><h2>${T('Make this space your own.','এই স্থান হোক আপনার।')}</h2></div><p>${T('Your new personalized activities, always at your pace.','নিজের গতিতে নতুন ব্যক্তিগত অনুশীলন।')}</p></div><div class="v3-dash-spotlight"><a href="#/landscape"><span>☀</span><strong>${T('Today’s emotional weather','আজকের অনুভূতির আকাশ')}</strong><small>${mostRecent?esc(mostRecent.label):T('What might your inner sky look like?','আজ মনের আকাশ কেমন?')}</small></a><a href="#/garden"><span>❀</span><strong>${T('Your growing garden','আপনার মনের বাগান')}</strong><small>${T(`${todayDone} caring moments reflected on today`,`${todayDone}টি যত্নের মুহূর্ত আজ`)}</small></a><a href="#/plan"><span>◷</span><strong>${T('A gentle plan for you','আপনার ছোট পরিকল্পনা')}</strong><small>${v3Data.plan?esc(v3FocusLabel(v3Data.plan.focus)):T('Choose a focus and begin','একটি বিষয় বেছে শুরু করুন')}</small></a></div><div class="v3-featuregrid">${v3Tiles()}</div></section>`;
 return dashboard().replace('</main>',extra+'</main>');}
const V3_SKIES=[
 {id:'sunrise',emoji:'☀',en:'Hopeful',bn:'আশাবাদী',scene:'sunrise',description:'There is some light in the day.',bnDesc:'আজ কিছুটা আলো আছে।',suggest:'Enjoy this moment. Think of one thing you would like to carry into tomorrow.',bnSuggest:'এই মুহূর্ত উপভোগ করুন। আগামীকালের জন্য একটি ভালো ভাবনা রাখুন।',mood:'calm'},
 {id:'clear',emoji:'✿',en:'Peaceful',bn:'শান্ত',scene:'clear',description:'Today feels steady and calm.',bnDesc:'আজ মন শান্ত ও স্থির।',suggest:'Notice what supports your calm. A small journal note can help you remember it.',bnSuggest:'কী আপনাকে শান্ত রাখে ভাবুন; ডায়েরিতে লিখতে পারেন।',mood:'calm'},
 {id:'cloudy',emoji:'☁',en:'Uncertain',bn:'অনিশ্চিত',scene:'cloudy',description:'Things are a little unclear.',bnDesc:'সবকিছু পরিষ্কার মনে হচ্ছে না।',suggest:'Choose one manageable task and allow the rest to wait.',bnSuggest:'একটি সহজ কাজ বেছে নিন; বাকিগুলো পরে করতে পারেন।',mood:'confused'},
 {id:'rain',emoji:'☂',en:'Feeling low',bn:'মন খারাপ',scene:'rain',description:'A little heaviness is here.',bnDesc:'মনে কিছুটা ভার আছে।',suggest:'Consider speaking with someone you trust. You deserve kindness, especially today.',bnSuggest:'বিশ্বাসের কাউকে বলুন; আজ নিজের প্রতি সদয় থাকুন।',mood:'low'},
 {id:'windy',emoji:'↝',en:'Restless',bn:'অস্থির',scene:'windy',description:'Thoughts are moving quickly.',bnDesc:'চিন্তা অনেক দ্রুত চলছে।',suggest:'Try the two-minute breathing guide and gently reconnect with your surroundings.',bnSuggest:'দুই মিনিটের শ্বাসের অনুশীলন করুন, চারপাশে মন দিন।',mood:'anxious'},
 {id:'storm',emoji:'⚡',en:'Overwhelmed',bn:'চাপে আছি',scene:'storm',description:'Today feels like a lot.',bnDesc:'আজ অনেক কিছু একসঙ্গে হচ্ছে।',suggest:'Pause, reduce demands where possible, and seek support if the pressure feels difficult to manage.',bnSuggest:'একটু বিরতি নিন, কাজ কমান, প্রয়োজনে সহায়তা চান।',mood:'stressed'}
];
function v3SceneMarkup(id){return `<div class="v3-sky-scene sky-${id}" role="img" aria-label="${esc(V3_SKIES.find(x=>x.id===id)?.en||'Sky illustration')}"><div class="v3-sky-glow"></div><div class="v3-sky-sun"></div><div class="v3-sky-cloud c1"></div><div class="v3-sky-cloud c2"></div><div class="v3-sky-hill back"></div><div class="v3-sky-hill front"></div><div class="v3-sky-flora">✽ <span>❋</span> ✽</div><div class="v3-raindrops">⋮ ⋮ ⋮ ⋮ ⋮</div></div>`;}
function v3Landscape(){const sky=V3_SKIES.find(x=>x.id===v3Scene)||V3_SKIES[0];return shell(`${v3Banner(T('EMOTION LANDSCAPE','অনুভূতির আকাশ'),T('What does your inner sky look like?','আজ মনের আকাশ কেমন?'),T('Choose the weather that feels closest to today. There is no correct answer.','আজকের অনুভূতির সঙ্গে সবচেয়ে মেলে এমন আকাশ বেছে নিন।'))}<section class="v3-landscape"><div class="v3-sky-wrap">${v3SceneMarkup(sky.id)}<div class="v3-sky-caption"><span>${T('YOUR SKY TODAY','আজকের মনের আকাশ')}</span><h2>${T(sky.en,sky.bn)}</h2><p>${T(sky.description,sky.bnDesc)}</p></div></div><div class="v3-sky-selector"><span class="v3-kicker">${T('SELECT YOUR FEELING','আপনার অনুভূতি বেছে নিন')}</span><div class="v3-sky-choices">${V3_SKIES.map(x=>`<button class="v3-sky-choice ${x.id===sky.id?'selected':''}" data-v3="sky-select" data-id="${x.id}" aria-pressed="${x.id===sky.id}"><span>${x.emoji}</span><strong>${T(x.en,x.bn)}</strong></button>`).join('')}</div><div class="v3-suggestion"><span class="v3-kicker">${T('A GENTLE NEXT STEP','পরবর্তী সহজ পদক্ষেপ')}</span><p>${T(sky.suggest,sky.bnSuggest)}</p><div class="v3-row"><button data-v3="sky-save" class="v3-main-button">${I('check',16)} ${T('Save this check-in','এই অনুভূতি রাখুন')}</button><a href="#/breathing" class="v3-outline-button">${T('Try breathing','শ্বাসের অনুশীলন')}</a></div></div><p class="v3-smallprint">${v3PrivateNote()}</p></div></section>`);}
function v3GardenScene(){const entries=v3Data.garden||[];const flowers=Math.min(16,Math.max(3,3+entries.length)),n=Array.from({length:flowers},(_,i)=>{let ang=((i*131)%335)+10,size=.72+(i%4)*.14,left=8+(i*17)%82,top=45+(i*23)%36;const petals=['✿','❀','✽','✾'][i%4];return `<span class="v3-garden-bloom" style="--x:${left}%;--y:${top}%;--sz:${size};--delay:${i*.08}s">${petals}</span>`;}).join('');return `<div class="v3-garden-art" role="img" aria-label="An illustrated peaceful garden with ${flowers} flowers"><div class="v3-garden-sun"></div><div class="v3-garden-cloud gc1"></div><div class="v3-garden-cloud gc2"></div><div class="v3-garden-mound mound-far"></div><div class="v3-garden-mound mound-near"></div>${n}<div class="v3-garden-path"></div><span class="v3-garden-butterfly">✦</span></div>`;}
const V3_CARE=[['breath','✧','Take a breathing pause','শ্বাসের বিরতি'],['rest','☾','Make room for rest','বিশ্রাম দিন'],['reflect','✎','Reflect on a feeling','অনুভূতি নিয়ে ভাবুন'],['connect','♡','Reach out to someone','কারও সঙ্গে কথা বলুন'],['gratitude','✿','Notice one good thing','একটি ভালো জিনিস দেখুন']];
function v3Garden(){const today=v3Today(),done=v3Data.garden.filter(x=>x.date===today);return shell(`${v3Banner(T('THE MIND GARDEN','মনের বাগান'),T('A little care helps things grow.','অল্প যত্নেও ফুল ফোটে।'),T('Your virtual garden celebrates caring actions. Missing a day never takes anything away.','যত্নের ছোট কাজগুলো মনের বাগানকে রাঙায়। বিরতি নিলে কিছুই হারায় না।'))}<section class="v3-garden-layout"><div><div class="v3-garden-intro">${pill(T('YOUR PEACEFUL CORNER','আপনার শান্ত স্থান'),'soft')}<h2>${T('Let your garden grow at its own pace.','আপনার বাগান নিজের গতিতে বেড়ে উঠুক।')}</h2><p>${T('Each reflected-on care activity adds another little bloom. The garden does not measure mood, progress, or clinical wellbeing.','প্রতিটি যত্নের কাজের স্মৃতিতে একটি নতুন ফুল। এই বাগান কোনো মানসিক স্বাস্থ্য স্কোর নয়।')}</p></div>${v3GardenScene()}</div><div class="v3-garden-panel"><span class="v3-kicker">${T('TODAY’S CARING MOMENTS','আজকের যত্নের মুহূর্ত')}</span><h3>${T('What felt possible today?','আজ কোন কাজটি করতে পেরেছেন?')}</h3><p>${T('Mark only activities you actually did. Each kind can be added once per day.','যা সত্যিই করেছেন শুধু সেটিই বেছে নিন। প্রতিটি কাজ দিনে একবার।')}</p>${V3_CARE.map(([id,icon,en,bn])=>`<button data-v3="garden-care" data-id="${id}" ${done.some(x=>x.kind===id)?'disabled':''} class="v3-care-option"><span>${icon}</span><strong>${T(en,bn)}</strong><small>${done.some(x=>x.kind===id)?T('Reflected today','আজ করা হয়েছে'):'+'}</small></button>`).join('')}<div class="v3-garden-summary"><b>${v3Data.garden.length}</b><span>${T('caring moments reflected on so far','এখন পর্যন্ত যত্নের মুহূর্ত')}</span></div><p class="v3-smallprint">${v3PrivateNote()}</p><a href="#/bromind" class="v3-inline">${T('Open Bro-minD exercises','ব্রো-মিন্ডের অনুশীলন খুলুন')} ↗</a></div></section>`);}
