function v3Journey(id){let story=V3_STORIES.find(s=>s.id===id);if(!story)return shell(`${v3Banner(T('LIFE JOURNEY','জীবনের সফর'),T('Every choice is a chance to reflect.','প্রতিটি সিদ্ধান্তে শেখার সুযোগ।'),T('Explore realistic student situations. These are reflections, not tests or diagnoses.','জীবনের পরিস্থিতি নিয়ে ভাবুন। এটি কোনো পরীক্ষা নয়।'))}<div class="v3-story-grid">${V3_STORIES.map(x=>`<a href="#/journey/${x.id}" class="v3-story-tile"><span>${x.emoji}</span><strong>${T(x.title,x.bn)}</strong><small>${T(x.hint,x.bnHint)}</small><b>${T('Explore the story','গল্পে যান')} ↗</b></a>`).join('')}</div><div class="v3-info-band">${T('Your answers are not scored or used to infer a disorder. You can explore different choices at any time.','উত্তরের কোনো নম্বর নেই, এবং রোগ নির্ণয় করা হয় না।')}</div>`);
 if(!v3Story||v3Story.id!==story.id)v3Story={id:story.id,index:0,choice:null,history:[]};const step=story.steps[v3Story.index];const done=v3Story.index>=story.steps.length;
 return shell(`${v3Banner(T('INTERACTIVE LIFE JOURNEY','জীবনের গল্প'),T(story.title,story.bn),T(story.hint,story.bnHint))}<a class="v3-back" href="#/journey">← ${T('All journeys','সব গল্প')}</a><section class="v3-story-stage"><div class="v3-story-art"><div class="v3-story-art-halo"></div><span>${story.emoji}</span><small>${T('Your story, your pace','আপনার গল্প, আপনার গতি')}</small></div><div class="v3-story-content"><span class="v3-kicker">${done?T('REFLECTION COMPLETE','শেষ ধাপ'):T(`CHAPTER ${v3Story.index+1} OF ${story.steps.length}`,`${v3Story.index+1}/${story.steps.length} অধ্যায়`)}</span>${done?`<h2>${T('Every step gave you something to consider.','প্রতিটি পদক্ষেপ ভাবার সুযোগ দিয়েছে।')}</h2><p>${T('There was no perfect route. Notice which choices felt most supportive and consider trying one small action in real life.','সঠিক একমাত্র পথ নেই। কোন সিদ্ধান্তটি কাজে লাগতে পারে ভাবুন।')}</p><div class="v3-row"><button class="v3-main-button" data-v3="story-complete">${T('Reflect in my Garden','বাগানে স্মৃতি রাখুন')}</button><button class="v3-outline-button" data-v3="story-restart">${T('Explore again','আবার দেখুন')}</button></div>`:
 `<h2>${T(step.en,step.bn)}</h2>${step.options.map((o,i)=>`<button class="v3-story-choice ${v3Story.choice===i?'chosen':''}" data-v3="story-choice" data-index="${i}" aria-pressed="${v3Story.choice===i}"><span>${String.fromCharCode(65+i)}</span>${T(o[0],o[1])}</button>`).join('')}${v3Story.choice!==null?`<div class="v3-story-feedback"><strong>${T('A thought to take with you','মনে রাখার একটি কথা')}</strong><p>${T(step.options[v3Story.choice][2],step.options[v3Story.choice][3])}</p></div>`:''}<div class="v3-row"><button class="v3-main-button" data-v3="story-next" ${v3Story.choice===null?'disabled':''}>${v3Story.index===story.steps.length-1?T('Finish reflection','শেষ করুন'):T('Continue story','পরের অধ্যায়')} →</button></div>`}</div></section>`);}
const V3_PROMPTS=[['open','What has been on your mind today?','আজ কী নিয়ে ভাবছেন?'],['gratitude','What is one small thing you appreciate?','আজকের একটি ভালো জিনিস কী?'],['kindness','What would you say to a friend feeling this way?','একই অনুভূতি হলে বন্ধুকে কী বলতেন?'],['strength','What helped you through a difficult moment?','কঠিন মুহূর্তে কী সাহায্য করেছে?'],['rest','What would make tomorrow a little gentler?','আগামীকাল একটু সহজ করতে কী করবেন?']];
let v3Prompt=V3_PROMPTS[0][0];
function v3Journal(){const prompt=V3_PROMPTS.find(p=>p[0]===v3Prompt)||V3_PROMPTS[0];return shell(`${v3Banner(T('THE MIND JOURNAL','মনের জার্নাল'),T('Give your thoughts a quiet page.','ভাবনাগুলোকে একটু জায়গা দিন।'),T('A private space to write. No labels, no judgment, no pressure to share.','নিজের ভাবনা লিখুন। অন্যকে দেখানোর কোনো চাপ নেই।'))}<div class="v3-journal-layout"><section class="v3-journal-paper"><div class="v3-journal-paper-top">✧ <span>${T('A NOTE TO MYSELF','নিজের জন্য লেখা')}</span> <span>${new Date().toLocaleDateString(state.lang==='bn'?'bn-IN':'en-IN',{month:'long',day:'numeric'})}</span></div><div class="v3-journal-prompts">${V3_PROMPTS.map(p=>`<button type="button" data-v3="journal-prompt" data-id="${p[0]}" class="${v3Prompt===p[0]?'selected':''}">${T(p[1],p[2])}</button>`).join('')}</div><form id="v3-journal-form"><label for="v3-journal-note" class="v3-journal-label">${T(prompt[1],prompt[2])}</label><textarea id="v3-journal-note" name="entry" rows="8" maxlength="1500" required placeholder="${T('Write as much or as little as you like...','যতটুকু ইচ্ছে লিখুন...')}"></textarea><label class="v3-journal-label" for="v3-journal-tag">${T('What fits this note?','এই লেখার অনুভূতি?')}</label><select id="v3-journal-tag" name="tag"><option value="reflective">${T('Reflective','ভাবনাময়')}</option><option value="grateful">${T('Grateful','কৃতজ্ঞ')}</option><option value="uncertain">${T('Uncertain','অনিশ্চিত')}</option><option value="hopeful">${T('Hopeful','আশাবাদী')}</option><option value="tired">${T('Tired','ক্লান্ত')}</option></select><div class="v3-row"><button class="v3-main-button" type="submit">${T('Keep this private note','নিজের লেখা রাখুন')} ${I('check',15)}</button></div></form><p class="v3-smallprint">${v3PrivateNote()}</p></section><aside class="v3-journal-archive"><span class="v3-kicker">${T('MY PAGES','আমার পাতাগুলি')}</span><h3>${T('Your reflection archive','আপনার লেখার সংগ্রহ')}</h3><p>${T('Entries are only on your device or in this session.','লেখাগুলি আপনার ডিভাইস বা এই সেশনে থাকে।')}</p>${v3Data.journal.length?`<div class="v3-journal-list">${[...v3Data.journal].reverse().map((j,i)=>`<article><div class="v3-journal-list-meta"><time>${esc(fmtDate(j.time))}</time><span>${esc(j.tag)}</span></div><p>${esc(j.text)}</p><button data-v3="journal-delete" data-id="${esc(j.id)}" aria-label="${T('Delete entry','লেখাটি মুছুন')}">✕ ${T('Delete','মুছুন')}</button></article>`).join('')}</div>`:`<div class="v3-empty"><span>✎</span><p>${T('Your first entry can begin on this page.','আপনার প্রথম লেখা এখানেই শুরু হতে পারে।')}</p></div>`}<div class="v3-row"><button class="v3-outline-button" data-v3="journal-export" ${!v3Data.journal.length?'disabled':''}>${I('download',16)} ${T('Export .txt','লেখা ডাউনলোড')}</button></div></aside></div>`);}
const V3_FOCUS={
 worry:{color:'mint',days:[['Make a small list of what is within your control.','যা আপনার হাতে আছে তার তালিকা করুন।'],['Try a gentle two-minute breathing pause.','দুই মিনিটের শ্বাসের অনুশীলন করুন।'],['Give a worry a name in your private journal.','ডায়েরিতে একটি দুশ্চিন্তার নাম দিন।'],['Share a concern with a trusted person.','বিশ্বাসের কারও সঙ্গে কথা বলুন।'],['Take a brief break from constant updates.','বারবার নতুন তথ্য দেখা থেকে একটু বিরতি নিন।'],['Do one manageable task, then pause.','একটি ছোট কাজ করে থামুন।'],['Notice one thing you handled with care.','যত্ন নিয়ে করা একটি কাজ মনে করুন।']]},
 rest:{color:'lavender',days:[['Choose a consistent time to begin winding down.','বিশ্রামের একটি নির্দিষ্ট সময় রাখুন।'],['Dim screens and lights before bedtime when possible.','সম্ভব হলে ঘুমের আগে আলো ও স্ক্রিন কমান।'],['Take a slow, comfortable breathing pause.','আরামদায়ক ধীর শ্বাস নিন।'],['Make tomorrow’s first task simple.','আগামীকালের প্রথম কাজটি সহজ রাখুন।'],['Spend ten minutes away from notifications.','দশ মিনিট নোটিফিকেশন থেকে দূরে থাকুন।'],['Make room for a pleasant, low-effort activity.','কম পরিশ্রমের আনন্দদায়ক কিছু করুন।'],['Reflect on what helped you rest.','কী বিশ্রামে সাহায্য করেছে ভাবুন।']]},
 study:{color:'sky',days:[['Write one realistic priority for today.','আজকের একটি বাস্তব লক্ষ্য লিখুন।'],['Try a focused 20-minute study interval.','২০ মিনিট মনোযোগ দিয়ে পড়ুন।'],['Put a short break into your schedule.','সময়সূচিতে একটি ছোট বিরতি রাখুন।'],['Identify a question to ask a teacher or peer.','শিক্ষক বা বন্ধুকে একটি প্রশ্ন জিজ্ঞেস করুন।'],['Clear or organize a small study space.','পড়ার জায়গাটি একটু গুছিয়ে নিন।'],['End a session by noting your next step.','পড়া শেষে পরের কাজটি লিখুন।'],['Review the week without comparing with others.','অন্যদের সঙ্গে তুলনা না করে সপ্তাহটি ভাবুন।']]},
 connection:{color:'rose',days:[['Send a kind message to someone you trust.','বিশ্বাসের কাউকে আন্তরিক বার্তা দিন।'],['Ask a friend how their day has been.','বন্ধুর দিনটি কেমন গেল জিজ্ঞেস করুন।'],['Notice a place where you feel welcome.','যেখানে আপন মনে হয় সেই স্থানটি ভাবুন।'],['Spend a moment doing something together.','কারও সঙ্গে কিছুক্ষণ সময় কাটান।'],['Share one small feeling with a safe person.','নিরাপদ কারও কাছে ছোট অনুভূতি বলুন।'],['Express appreciation to someone.','কাউকে কৃতজ্ঞতা জানান।'],['Reflect on the connections you value.','মূল্যবান সম্পর্কগুলোর কথা ভাবুন।']]},
 hope:{color:'apricot',days:[['Notice one thing that made today easier.','আজকের একটি স্বস্তির মুহূর্ত দেখুন।'],['Step outdoors or toward natural light if possible.','সম্ভব হলে প্রাকৃতিক আলোয় কিছুক্ষণ থাকুন।'],['Choose a tiny enjoyable activity.','আনন্দের ছোট একটি কাজ করুন।'],['Remember one difficulty you have navigated.','অতীতে সামলানো একটি সমস্যা মনে করুন।'],['Reach out to a person who feels supportive.','সহায়ক কারও সঙ্গে কথা বলুন।'],['Make a simple plan for something pleasant.','আনন্দদায়ক কিছুর সহজ পরিকল্পনা করুন।'],['Write one kind sentence to yourself.','নিজেকে একটি সদয় বাক্য লিখুন।']]}
};
function v3Advice(){const last=state.type&&state.answers[state.type]&&state.answers[state.type].every(x=>Number.isInteger(x))?score(state.type):null;
 if(!last)return {focus:'study',because:T('No recent assessment has been completed in this session. You can select any focus.','এই সেশনে মূল্যায়ন সম্পূর্ণ হয়নি। যেকোনো বিষয় বেছে নিন।'),why:T('This plan is chosen by you, not generated from a diagnosis.','এই পরিকল্পনা আপনার বেছে নেওয়া, রোগ নির্ণয় নয়।')};
 const focus=state.type==='anxious'?'worry':state.type==='stressed'?'study':state.type==='depressed'?'hope':'rest';
 return {focus,because:T(`You completed a ${FEELINGS[state.type].title.toLowerCase()} reflection with a response-frequency index of ${last.pct}%. A related everyday-care focus may be useful.`,`আপনি একটি অনুভূতি যাচাই সম্পন্ন করেছেন (${last.pct}%)। সংশ্লিষ্ট সহজ অভ্যাস কাজে লাগতে পারে।`),why:T('This is a transparent if-then suggestion from your selected assessment category. The percentage is not a diagnostic probability.','এটি আপনার নির্বাচিত বিষয়ের ভিত্তিতে একটি সহজ নিয়ম। শতাংশটি রোগের সম্ভাবনা নয়।')};}
function v3Plan(){const advice=v3Advice(),plan=v3Data.plan;let suggestions=plan?V3_FOCUS[plan.focus].days:[];return shell(`${v3Banner(T('PERSONAL WELLBEING PLAN','ব্যক্তিগত সুস্থতার পরিকল্পনা'),T('One small caring action each day.','প্রতিদিন একটি ছোট যত্নের কাজ।'),T('Choose an everyday focus and take the activities at your own pace. No streaks or penalties.','একটি বিষয় বেছে নিজের গতিতে এগোন। কোনো শাস্তি বা প্রতিযোগিতা নেই।'))}<div class="v3-plan-layout"><section class="v3-plan-create"><div class="v3-rule-note"><span>${I('spark',19)}</span><div><strong>${T('An explainable starting point','বোঝার মতো একটি পরামর্শ')}</strong><p>${advice.because}</p><small>${advice.why}</small></div></div><form id="v3-plan-form"><label class="v3-kicker" for="v3-focus">${T('MY CURRENT FOCUS','আমার বর্তমান লক্ষ্য')}</label><div class="v3-plan-options">${Object.keys(V3_FOCUS).map(f=>`<label><input type="radio" name="focus" value="${f}" ${(plan?.focus||advice.focus)===f?'checked':''}><span>${v3FocusLabel(f)}</span></label>`).join('')}</div><label class="v3-kicker" for="v3-duration">${T('PLAN LENGTH','কতদিনের পরিকল্পনা')}</label><select name="duration" id="v3-duration"><option value="7" ${plan?.duration===7?'selected':''}>${T('7 gentle days','৭ দিনের পরিকল্পনা')}</option><option value="14" ${plan?.duration===14?'selected':''}>${T('14 gentle days','১৪ দিনের পরিকল্পনা')}</option></select><button type="submit" class="v3-main-button">${plan?T('Update my plan','পরিকল্পনা বদলান'):T('Begin my gentle plan','পরিকল্পনা শুরু করুন')} ↗</button></form><p class="v3-smallprint">${v3PrivateNote()}</p></section><section class="v3-plan-list"><div class="v3-plan-top"><div><span class="v3-kicker">${T('MY STEPS','আমার ধাপগুলি')}</span><h2>${plan?esc(v3FocusLabel(plan.focus)):T('Your daily plan will appear here.','প্রতিদিনের কাজ এখানে দেখা যাবে।')}</h2></div>${plan?pill(`${plan.done.length} / ${plan.duration}`,'soft'):''}</div>${plan?Array.from({length:plan.duration},(_,i)=>{let d=suggestions[i%7],finished=plan.done.includes(i);return `<button data-v3="plan-step" data-index="${i}" class="v3-plan-day ${finished?'finished':''}"><span class="v3-plan-daynum">${String(i+1).padStart(2,'0')}</span><span><strong>${T('Day','দিন')} ${i+1}</strong><small>${T(d[0],d[1])}</small></span><span class="v3-plan-check">${finished?'✓':'○'}</span></button>`;}).join(''):`<div class="v3-empty"><span>◷</span><p>${T('Choose a focus and begin when it feels right.','যখন ইচ্ছা একটি বিষয় বেছে শুরু করুন।')}</p></div>`}${plan?`<p class="v3-smallprint">${T('You can undo any completed step by selecting it again. Days are flexible, not scheduled deadlines.','কোনো ধাপ আবার নির্বাচন করে পরিবর্তন করা যায়। সময়সীমার চাপ নেই।')}</p>`:''}</section></div>`);}
function v3WeekData(){let days=Array.from({length:7},(_,k)=>{let dt=new Date();dt.setHours(12,0,0,0);dt.setDate(dt.getDate()-(6-k));return {key:dt.toLocaleDateString('en-CA'),label:dt.toLocaleDateString(state.lang==='bn'?'bn-IN':'en-IN',{weekday:'short'}),entries:[],avg:null};});for(const e of state.entries.filter(x=>x.kind==='mood')){const key=new Date(e.time).toLocaleDateString('en-CA');const d=days.find(x=>x.key===key);if(d&&Number.isFinite(Number(e.energy)))d.entries.push(Number(e.energy));}for(const d of days)d.avg=d.entries.length?d.entries.reduce((a,b)=>a+b,0)/d.entries.length:null;return days;}
function v3Insights(){let days=v3WeekData(),filled=days.filter(d=>d.avg!==null),totalDiary=state.entries.filter(e=>e.kind==='mood').length;
 const lastReport=state.type&&state.answers[state.type]?.every(x=>Number.isInteger(x))?score(state.type):null;const why=v3Advice();return shell(`${v3Banner(T('MY WELLBEING INSIGHTS','আমার পর্যবেক্ষণ'),T('Notice what your days are telling you.','নিজের দিনগুলোকে আরও বুঝুন।'),T('Understand self-reported patterns without treating them as diagnoses or predictions.','নিজের দেওয়া তথ্যের ধরণ বুঝুন; রোগ নির্ণয় বা ভবিষ্যদ্বাণী নয়।'))}<section class="v3-stat-grid"><article><span>${T('Mood diary entries','মুড ডায়েরির লেখা')}</span><b>${totalDiary}</b><small>${T('Current browser / session','বর্তমান ব্রাউজার / সেশন')}</small></article><article><span>${T('Mind Journal notes','মনের জার্নাল')}</span><b>${v3Data.journal.length}</b><small>${T('Private reflections','ব্যক্তিগত ভাবনা')}</small></article><article><span>${T('Caring moments','নিজের যত্ন')}</span><b>${v3Data.garden.length}</b><small>${T('Garden reflections','বাগানের স্মৃতি')}</small></article><article><span>${T('Life journeys explored','জীবনের গল্প')}</span><b>${v3Data.journeys.length}</b><small>${T('Completed stories','সম্পূর্ণ গল্প')}</small></article></section><div class="v3-insights-grid"><section class="v3-insight-panel"><span class="v3-kicker">${T('LAST 7 DAYS','শেষ ৭ দিন')}</span><h2>${T('Energy check-ins','শক্তির পর্যবেক্ষণ')}</h2><p>${T('Mean selected energy level (1 to 5) for each day you recorded one or more diary entries.','ডায়েরির ভিত্তিতে প্রতিদিনের গড় শক্তির মাত্রা (১-৫)।')}</p><div class="v3-bars">${days.map(d=>`<div class="v3-bar-col"><span>${d.avg!==null?d.avg.toFixed(1):'—'}</span><div class="v3-bar-track"><div style="height:${d.avg!==null?d.avg/5*100:0}%" class="v3-bar-fill"></div></div><small>${esc(d.label)}</small></div>`).join('')}</div>${!filled.length?`<div class="v3-empty small">${T('Add a mood diary entry to start seeing your own patterns.','মুড ডায়েরিতে লিখলে পরিবর্তন দেখতে পাবেন।')}</div>`:''}<a href="#/diary" class="v3-inline">${T('Open Mood Diary','মুড ডায়েরি খুলুন')} ↗</a></section><section class="v3-insight-panel"><span class="v3-kicker">${T('TRANSPARENT REASONING','সহজে বোঝার মতো যুক্তি')}</span><h2>${T('Why a plan may be suggested','কেন কোনো পরিকল্পনা সাজেস্ট করা হয়')}</h2><div class="v3-rule-flow"><div><span>01</span><b>${T('Selected assessment','নির্বাচিত মূল্যায়ন')}</b><small>${lastReport?T(`${FEELINGS[state.type].title} · ${lastReport.pct}% response index`,`${FEELINGS_BN[state.type]} · ${lastReport.pct}%`):T('None completed in this session','এই সেশনে নেই')}</small></div><div><span>02</span><b>${T('Visible recommendation rule','স্পষ্ট পরামর্শের নিয়ম')}</b><small>${lastReport?`${esc(state.type)} → ${esc(v3FocusLabel(why.focus))}`:T('No assessment → open choice','মূল্যায়ন নেই → নিজের পছন্দ')}</small></div><div><span>03</span><b>${T('Optional next step','ইচ্ছাধীন পরের ধাপ')}</b><small>${v3FocusLabel(why.focus)}</small></div></div><p class="v3-smallprint">${T('This is explainable, user-directed rule logic. It is not a trained prediction model or a clinical decision system.','এটি সহজ নিয়মভিত্তিক পরামর্শ; চিকিৎসাগত সিদ্ধান্ত বা প্রশিক্ষিত পূর্বাভাস মডেল নয়।')}</p><a href="#/plan" class="v3-inline">${T('Open personal plan','ব্যক্তিগত পরিকল্পনা')} ↗</a><span class="v3-link-spacer"> · </span><a href="#/mindmap" class="v3-inline">${T('Open Mind Map','মনের মানচিত্র')} ↗</a></section></div>`);}
function v3MindMap(){const lastSky=v3Data.landscape.slice(-1)[0],lastMood=state.entries.filter(x=>x.kind==='mood').slice(-1)[0],advice=v3Advice();
 const finished=[...new Set(v3Data.garden.map(x=>x.kind))],memo=finished.length?finished.map(x=>({breath:T('Breathing','শ্বাস'),reflect:T('Reflection','ভাবনা'),rest:T('Rest','বিশ্রাম'),connect:T('Connection','সম্পর্ক'),gratitude:T('Gratitude','কৃতজ্ঞতা')})[x]||x).join(', '):T('No activities added yet','এখনও কোনো অনুশীলন নেই');
 const nodes=[{id:'weather',icon:'☀',label:T('Recent emotional weather','সাম্প্রতিক মনের আকাশ'),value:lastSky?esc(lastSky.label):T('Not recorded yet','এখনও লিখেননি')},{id:'mood',icon:'◈',label:T('Last diary check-in','শেষ ডায়েরি'),value:lastMood?esc(lastMood.mood):T('Not recorded yet','এখনও লিখেননি')},{id:'focus',icon:'◷',label:T('Suggested everyday focus','সহজ যত্নের বিষয়'),value:v3FocusLabel(advice.focus)},{id:'care',icon:'✿',label:T('Care activities noticed','নিজের যত্নের কাজ'),value:esc(memo)},{id:'support',icon:'♡',label:T('Ways to seek support','সহায়তার পথ'),value:T('Trusted people · Tele-MANAS','বিশ্বাসের মানুষ · টেলি-মানস')}];
 return shell(`${v3Banner(T('MY MIND MAP','মনের মানচিত্র'),T('Connect the pieces of your day.','দিনের অনুভূতিগুলো একসঙ্গে দেখুন।'),T('An explainable map of your own entries, activities and resources - relationships shown here are organizational, not medical findings or causes.','আপনার লেখা, অনুশীলন ও সহায়তার একটি চিত্র। এটি চিকিৎসাগত সম্পর্ক বা কারণ প্রমাণ করে না।'))}<section class="v3-map-stage"><svg class="v3-map-lines" viewBox="0 0 1000 600" preserveAspectRatio="none" aria-hidden="true"><path d="M500 295 L200 105 M500 295 L815 105 M500 295 L190 485 M500 295 L820 490 M500 295 L500 550" fill="none" stroke="#9dbeb1" stroke-width="2" stroke-dasharray="6 9"/></svg><div class="v3-map-core"><span>✳</span><strong>${T('My wellbeing','আমার সুস্থতা')}</strong><small>${T('My personal reflections','নিজের অনুভূতি')}</small></div>${nodes.map(x=>`<div class="v3-map-node node-${x.id}"><span>${x.icon}</span><strong>${x.label}</strong><small>${x.value}</small></div>`).join('')}</section><div class="v3-map-bottom"><section><span class="v3-kicker">${T('HOW THIS MAP IS CREATED','এই মানচিত্রের তথ্য')}</span><h2>${T('Only what you actually recorded.','শুধু আপনার দেওয়া তথ্য।')}</h2><p>${T('The map displays the latest entries and the explicit recommendation rule. It does not infer personality, disorder, risk, or a causal relationship. Missing entries stay marked as missing.','এখানে শুধু সাম্প্রতিক লেখা ও স্পষ্ট পরামর্শের নিয়ম আছে; রোগ বা কারণ অনুমান করে না।')}</p></section><div class="v3-map-bottomlinks"><a href="#/landscape" class="v3-outline-button">${T('Update feeling','অনুভূতি লিখুন')} ↗</a><a href="#/garden" class="v3-outline-button">${T('Visit garden','বাগানে যান')} ↗</a><a href="#/insights" class="v3-outline-button">${T('View charts','চার্ট দেখুন')} ↗</a></div></div>`);}
function v3Relaxation(){return shell(`${v3Banner(T('BRO-MIND · RELAXATION ROOM','ব্রো-মিন্ড · শান্তির ঘর'),T('A quiet corner, whenever you need one.','প্রয়োজন হলেই শান্তির একটি স্থান।'),T('Mix gentle generated ambient sounds with guided breathing and spoken meditation.','হালকা তৈরি করা পরিবেশধ্বনি, শ্বাস ও কণ্ঠ নির্দেশনা।'))}<div class="v3-relax-layout"><section class="v3-relax-art"><div class="v3-relax-circle"><div class="v3-relax-orbit"></div><span>✺</span></div><h2>${T('Find a moment of stillness.','স্থিরতার একটি মুহূর্ত।')}</h2><p>${T('You can listen, breathe, or simply rest. The sounds are synthesized in your browser, not nature recordings.','শুনুন, শ্বাস নিন বা বিশ্রাম করুন। শব্দগুলি ব্রাউজারে তৈরি, প্রকৃতির রেকর্ডিং নয়।')}</p></section><section class="v3-relax-controls"><span class="v3-kicker">${T('AMBIENCE','পরিবেশধ্বনি')}</span><h3>${T('Choose a calm soundscape','শান্ত শব্দ বেছে নিন')}</h3><div class="v3-sound-grid"><button data-v3="sound" data-id="rain" class="${v3Sound==='rain'?'selected':''}"><span>☂</span><strong>${T('Soft rain','হালকা বৃষ্টি')}</strong></button><button data-v3="sound" data-id="waves" class="${v3Sound==='waves'?'selected':''}"><span>≋</span><strong>${T('Ocean hush','সাগরের শব্দ')}</strong></button><button data-v3="sound" data-id="forest" class="${v3Sound==='forest'?'selected':''}"><span>♧</span><strong>${T('Forest breeze','বনের বাতাস')}</strong></button><button data-v3="sound-stop" class="${!v3Sound?'selected':''}"><span>◯</span><strong>${T('Silence','নীরবতা')}</strong></button></div><label for="v3-volume" class="v3-slider-label">${T('Volume','শব্দের মাত্রা')}</label><input id="v3-volume" type="range" min="0" max="70" value="25" aria-label="Sound volume"/><hr/><span class="v3-kicker">${T('SPOKEN GUIDANCE','কণ্ঠ নির্দেশনা')}</span><h3>${T('Listen in your language','নিজের ভাষায় শুনুন')}</h3><label for="v3-voice-lang">${T('Guide language','নির্দেশনার ভাষা')}</label><select id="v3-voice-lang"><option value="en-IN">English</option><option value="bn-IN">বাংলা</option><option value="hi-IN">हिन्दी</option></select><div class="v3-row"><button data-v3="voice-guide" class="v3-main-button">${I('volume',15)} ${T('Play voice guide','কণ্ঠ শুনুন')}</button><button data-v3="voice-stop" class="v3-outline-button">${T('Stop voice','কণ্ঠ বন্ধ')}</button></div><p class="v3-smallprint">${T('Voices depend on your device. Audio only begins after you select a control and stops when you leave this page.','কণ্ঠের সুবিধা ডিভাইসের উপর নির্ভর করে। নিজে শুরু করলে তবেই শব্দ বাজবে।')}</p><div class="v3-row"><a class="v3-inline" href="#/breathing">${T('Guided breathing','শ্বাসের অনুশীলন')} ↗</a><a class="v3-inline" href="#/meditation">${T('Meditation timer','ধ্যানের সময়')} ↗</a></div></section></div>`);}
function v3Access(){return shell(`${v3Banner(T('ACCESSIBILITY & CONTROL','অ্যাক্সেসিবিলিটি ও নিয়ন্ত্রণ'),T('Make Mind-sage easier to use.','নিজের মতো করে ব্যবহার করুন।'),T('Choose how the site looks and behaves, and understand what stays on your device.','সাইটের অক্ষর, রং, গতিবিধি ও ডিভাইসের তথ্য নিয়ন্ত্রণ করুন।'))}<div class="v3-access-grid"><section class="v3-access-panel"><h2>${T('Reading and comfort','পড়া ও আরাম')}</h2><p>${T('These preferences are saved locally.','এই পছন্দগুলো শুধু ব্রাউজারে রাখা হয়।')}</p><div class="v3-access-row"><div><strong>${T('Text size','অক্ষরের আকার')}</strong><small>${T('Increase general text for easier reading.','সহজে পড়ার জন্য অক্ষর বড় করুন।')}</small></div><div class="v3-segments"><button data-v3="font" data-id="normal" class="${v3Prefs.font==='normal'?'selected':''}">A</button><button data-v3="font" data-id="large" class="${v3Prefs.font==='large'?'selected':''}">A+</button><button data-v3="font" data-id="xlarge" class="${v3Prefs.font==='xlarge'?'selected':''}">A++</button></div></div><div class="v3-access-row"><div><strong>${T('High contrast','বেশি কনট্রাস্ট')}</strong><small>${T('Stronger borders and colors.','রঙের পার্থক্য বাড়ান।')}</small></div><button data-v3="contrast" class="v3-switch ${v3Prefs.contrast?'on':''}" aria-pressed="${v3Prefs.contrast}">${v3Prefs.contrast?T('On','চালু'):T('Off','বন্ধ')}</button></div><div class="v3-access-row"><div><strong>${T('Reduce motion','অ্যানিমেশন কমান')}</strong><small>${T('Limit decorative movements.','সাজসজ্জার চলাচল কমান।')}</small></div><button data-v3="motion" class="v3-switch ${v3Prefs.motion?'on':''}" aria-pressed="${v3Prefs.motion}">${v3Prefs.motion?T('On','চালু'):T('Off','বন্ধ')}</button></div></section><section class="v3-access-panel"><h2>${T('Install & offline access','ইনস্টল ও অফলাইনে ব্যবহার')}</h2><div class="v3-install-mark">${I('download',34)}</div><p>${T('Install Mind-sage on your phone or desktop. Cached pages, exercises, and the Swamiji portrait can work without an internet connection after your first online visit. External support links require internet.','ফোন বা কম্পিউটারে ইনস্টল করতে পারেন। একবার অনলাইনে খোলার পর বেশির ভাগ অংশ অফলাইনে চলবে।')}</p><button class="v3-main-button" data-v3="install">${T('Install Mind-sage','মাইন্ড-সেজ ইনস্টল করুন')} ${I('arrow',17)}</button><p id="v3-install-msg" class="v3-smallprint">${T('If no install prompt appears, use your browser menu → Install app / Add to Home Screen.','ব্রাউজারের মেনু থেকে Install app বা Add to Home Screen বেছে নিন।')}</p><p class="v3-smallprint">${T('PWA installation requires HTTPS, as provided by GitHub Pages.','GitHub Pages-এর HTTPS-এ ইনস্টল সুবিধা পাওয়া যায়।')}</p></section><section class="v3-access-panel"><h2>${T('Your personal information','আপনার ব্যক্তিগত তথ্য')}</h2><p>${T('The static site does not upload questionnaire, journal, or diary responses. For adults, explicitly saved entries live in this browser. Under-18 entries are session-only.','এই সাইট উত্তর সার্ভারে পাঠায় না। প্রাপ্তবয়স্কদের সেভ করা তথ্য এই ব্রাউজারে থাকে; শিশুদের শুধু সেশনে।')}</p><div class="v3-info-band">${T('Clearing browser storage removes saved local entries. Downloaded files must be deleted separately.','ব্রাউজারের তথ্য মুছলে সেভ করা লেখা মুছে যায়। ডাউনলোড আলাদা করে মুছতে হবে।')}</div><button class="v3-danger-button" data-v3="wipe">${I('trash',16)} ${T('Clear my saved local entries','সেভ করা তথ্য মুছুন')}</button><a class="v3-inline" href="#/privacy">${T('Read complete privacy details','গোপনীয়তার বিস্তারিত')} ↗</a></section><section class="v3-access-panel"><h2>${T('Help is always available','সহায়তা পাওয়া যায়')}</h2><p>${T('If a concern is interfering with daily life, consider discussing it with a professional or someone you trust.','দৈনন্দিন জীবন কঠিন হলে বিশেষজ্ঞ বা বিশ্বাসের কারও সাহায্য নিন।')}</p><div class="v3-helplines"><a href="tel:14416">Tele-MANAS <strong>14416</strong></a><a href="tel:112">${T('Emergency','জরুরি')} <strong>112</strong></a><a href="tel:1098">${T('Child Helpline','শিশু সহায়তা')} <strong>1098</strong></a></div><a class="v3-inline" href="#/support">${T('Support directory','সহায়তার ঠিকানা')} ↗</a></section></div>`);}
function v3Connect(){const config=window.MIND_SAGE_CONFIG||{},burl=String(config.approvedBookingUrl||'');const safeUrl=/^https:\/\//.test(burl)?burl:'';return shell(`${v3Banner(T('SUPPORT CONNECT','বিশেষজ্ঞ সহায়তা'),T('Make the next step easier.','পরের ধাপকে সহজ করুন।'),T('Prepare for a conversation with a qualified counsellor or clinician, if you choose.','প্রয়োজন হলে কাউন্সেলর বা চিকিৎসকের সঙ্গে আলোচনার প্রস্তুতি নিন।'))}<div class="v3-connect-layout"><section class="v3-access-panel"><span class="v3-kicker">${T('PERSONAL HANDOFF','নিজের তথ্য নিয়ে আলোচনা')}</span><h2>${T('Prepare a discussion summary','আলোচনার সারসংক্ষেপ প্রস্তুত করুন')}</h2><p>${T('You control whether to download a personal assessment report and share it with someone you trust. Nothing is transferred automatically.','আপনি চাইলে রিপোর্ট ডাউনলোড করে শেয়ার করতে পারবেন; স্বয়ংক্রিয়ভাবে পাঠানো হবে না।')}</p><div class="v3-connection-steps"><div><b>01</b><span>${T('Complete a check-in','মূল্যায়ন সম্পূর্ণ করুন')}</span></div><div><b>02</b><span>${T('Download your own report','নিজের রিপোর্ট ডাউনলোড করুন')}</span></div><div><b>03</b><span>${T('Choose a support service','সহায়তা পরিষেবা বেছে নিন')}</span></div></div><a href="#/moods" class="v3-main-button">${T('Open assessments','মূল্যায়ন খুলুন')} ↗</a></section><section class="v3-access-panel"><span class="v3-kicker">${T('FIND A PROFESSIONAL','বিশেষজ্ঞ খুঁজুন')}</span><h2>${T('Connect with approved services','অনুমোদিত পরিষেবায় যোগাযোগ')}</h2><p>${T('Your university or a qualified provider can supply an authorized appointment link. An appointment is not booked until their own service confirms it.','বিশ্ববিদ্যালয় বা যোগ্য চিকিৎসা প্রদানকারী অনুমোদিত অ্যাপয়েন্টমেন্ট লিংক দিতে পারেন। তাদের নিশ্চিতকরণ ছাড়া বুকিং হয় না।')}</p>${safeUrl?`<a class="v3-main-button" rel="noopener noreferrer" target="_blank" href="${esc(safeUrl)}">${T('Open approved booking service','অ্যাপয়েন্টমেন্ট পরিষেবা খুলুন')} ↗</a>`:`<div class="v3-pending">${I('lock',22)}<div><strong>${T('Appointment connection not configured','অ্যাপয়েন্টমেন্ট লিংক এখনো সেট করা হয়নি')}</strong><small>${T('For now, contact your institution’s student wellbeing office or use the verified public support directory.','আপনার প্রতিষ্ঠানের কাউন্সেলিং পরিষেবা বা সরকারি সহায়তায় যোগাযোগ করুন।')}</small></div></div>`}<a class="v3-inline" href="#/support">${T('Verified public support services','যাচাই করা সরকারি সহায়তা')} ↗</a></section></div><section class="v3-integration"><span class="v3-kicker">${T('FOR INSTITUTIONAL DEPLOYMENT','প্রাতিষ্ঠানিক ব্যবহারের জন্য')}</span><h2>${T('Research & professional access roadmap','গবেষণা ও বিশেষজ্ঞ পরিষেবার পরিকল্পনা')}</h2><div class="v3-integrations-grid"><article><span>◈</span><h3>${T('Clinician workspace','বিশেষজ্ঞ ওয়ার্কস্পেস')}</h3><p>${T('Planned secure role-based access for authorized clinicians, with user-granted sharing and audit logging. No live patient dashboard is connected in this GitHub Pages release.','অনুমোদিত বিশেষজ্ঞদের জন্য নিরাপদ অ্যাক্সেসের পরিকল্পনা; এখন কোনো রোগীর ড্যাশবোর্ড সংযুক্ত নয়।')}</p></article><article><span>▦</span><h3>${T('University research','বিশ্ববিদ্যালয় গবেষণা')}</h3><p>${T('Planned consent-driven, ethics-approved survey collection and aggregate reporting through a protected research service. No shared participant database is currently collecting data.','সম্মতি ও নৈতিক অনুমোদন অনুযায়ী ভবিষ্যতে গবেষণা সংগ্রহের ব্যবস্থা; এখন কোনো শেয়ার্ড ডেটাবেস নেই।')}</p></article><article><span>♡</span><h3>${T('Accounts & appointments','অ্যাকাউন্ট ও অ্যাপয়েন্টমেন্ট')}</h3><p>${T('Require a separately hosted, properly secured backend and verified institutional partners. They cannot safely run on GitHub Pages alone.','এগুলোর জন্য নিরাপদ আলাদা সার্ভার এবং অনুমোদিত প্রতিষ্ঠান দরকার।')}</p></article></div></section>`);}
function v3Companion(){const base=companion();let integration=`<section class="v3-ai-box"><div><span class="v3-kicker">${T('OPTIONAL CONNECTED AI · PREVIEW INTEGRATION','ঐচ্ছিক এআই পরিষেবা')}</span><h2>${T('A more conversational companion','আরও স্বাভাবিক কথোপকথন')}</h2><p>${T('The existing private rule-based companion above always works. A connected AI experience is optional and requires a separately hosted secure server; it is not configured in the default GitHub Pages release.','উপরের নিয়মভিত্তিক সহায়ক সব সময় চলবে। সংযুক্ত এআই-এর জন্য আলাদা নিরাপদ সার্ভার প্রয়োজন।')}</p></div>${window.MIND_SAGE_CONFIG?.aiEndpoint&&adult()?`<form id="v3-ai-form"><label><input type="checkbox" name="consent" required> ${T('I understand this message will be sent to a configured server for a response.','এই বার্তা প্রতিক্রিয়ার জন্য সংযুক্ত সার্ভারে যাবে, আমি বুঝেছি।')}</label><textarea name="message" rows="3" maxlength="800" required placeholder="${T('Write a short message...','ছোট বার্তা লিখুন...')}"></textarea><button class="v3-main-button" type="submit">${T('Send to connected companion','সংযুক্ত সহায়ককে পাঠান')}</button><div id="v3-ai-response" aria-live="polite"></div></form>`:`<div class="v3-pending">${I('shield',23)}<div><strong>${T(!adult()?'Connected AI is only considered for adult users':'Secure AI service not connected',!adult()?'অপ্রাপ্তবয়স্কদের জন্য সংযুক্ত এআই নেই':'নিরাপদ এআই পরিষেবা যুক্ত নয়')}</strong><small>${T('The included backend starter explains how to enable this after a separate safety and privacy review.','আলাদা যাচাইয়ের পর সংযুক্ত করার নির্দেশনা প্যাকেজে আছে।')}</small></div></div>`}</section>`;return base.replace('</main>',integration+'</main>');}
function v3ApplyPrefs(){document.documentElement.dataset.v3Font=v3Prefs.font;document.body.classList.toggle('v3-contrast',!!v3Prefs.contrast);document.body.classList.toggle('v3-reduced-motion',!!v3Prefs.motion);}
function v3AfterNavigate(page){document.title='Mind-sage V3 | '+(navs.find(x=>x[0]===page)?.[2]||page);v3ApplyPrefs();if(page!=='relaxation')v3StopSound();if(adult()&&!v3Loaded){v3Load();if(page==='dashboard')render();}const sidebar=document.querySelector('.brand small');if(sidebar)sidebar.textContent='YOUR WELLBEING JOURNEY · V3';const sidebarBottom=document.querySelector('.sidebar-bottom');if(sidebarBottom&&!sidebarBottom.querySelector('.v3-side-install'))sidebarBottom.insertAdjacentHTML('afterbegin',`<a href="#/access" class="v3-side-install">${I('download',15)} ${T('Install app & accessibility','ইনস্টল ও সুবিধা')} ↗</a>`);}
let v3DraftNote='';
function v3StopSound(){if(v3Audio){try{v3Audio.oscillators?.forEach(o=>o.stop());v3Audio.context.close();}catch(_){}v3Audio=null;}v3Sound=null;}
async function v3PlaySound(id){v3StopSound();const AC=window.AudioContext||window.webkitAudioContext;if(!AC){alert(T('This browser does not support generated audio.','এই ব্রাউজারে শব্দ তৈরি করা যায় না।'));return;}try{const ctx=new AC(),src=ctx.createBufferSource(),buffer=ctx.createBuffer(1,ctx.sampleRate*2,ctx.sampleRate),data=buffer.getChannelData(0);for(let i=0;i<data.length;i++)data[i]=(Math.random()*2-1)*.7;src.buffer=buffer;src.loop=true;
 const filter=ctx.createBiquadFilter();filter.type=id==='rain'?'highpass':'lowpass';filter.frequency.value=id==='rain'?520:(id==='waves'?350:980);
 const g=ctx.createGain();g.gain.value=.11;src.connect(filter);filter.connect(g);g.connect(ctx.destination);src.start();const oscillators=[];
 if(id==='waves'){const osc=ctx.createOscillator(),gain=ctx.createGain();osc.frequency.value=.12;gain.gain.value=.075;osc.connect(gain);gain.connect(g.gain);osc.start();oscillators.push(osc);}
 if(id==='forest'){const osc=ctx.createOscillator(),tone=ctx.createGain();osc.type='sine';osc.frequency.value=550;tone.gain.value=.002;osc.connect(tone);tone.connect(ctx.destination);osc.start();oscillators.push(osc);}
 v3Sound=id;v3Audio={context:ctx,src,filter,g,oscillators};const slider=document.querySelector('#v3-volume');if(slider)v3Volume(Number(slider.value));render();}
 catch(err){console.warn('Audio unavailable',err);v3StopSound();alert(T('Audio cannot start on this browser.','এই ব্রাউজারে শব্দ চালু করা যাচ্ছে না।'));}}
function v3Volume(n){if(v3Audio)v3Audio.g.gain.value=Math.max(0,Math.min(.7,n/100))*.23;}
function v3Voice(){if(!('speechSynthesis' in window)){alert(T('Speech guidance is not supported on this browser.','এই ব্রাউজারে কণ্ঠ নির্দেশনা নেই।'));return;}const lang=document.querySelector('#v3-voice-lang')?.value||'en-IN';const scripts={
'en-IN':'Find a comfortable posture. Let your shoulders soften. Take a gentle breath in and a slow breath out. Notice the ground supporting you. You do not have to solve everything right now. Return to your breath whenever you are ready.',
'bn-IN':'আরাম করে বসুন। কাঁধের চাপ ছেড়ে দিন। ধীরে শ্বাস নিন, ধীরে শ্বাস ছাড়ুন। মাটির সমর্থন অনুভব করুন। এই মুহূর্তে সব সমাধান করার দরকার নেই। প্রস্তুত হলে আবার শ্বাসের দিকে মন দিন।',
'hi-IN':'आराम से बैठें। कंधों को ढीला छोड़ें। धीरे-धीरे साँस लें और छोड़ें। ज़मीन का सहारा महसूस करें। इस पल सब कुछ हल करना ज़रूरी नहीं है। तैयार होने पर फिर अपनी साँस पर ध्यान दें।'};
 speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(scripts[lang]);u.lang=lang;u.rate=.82;u.pitch=1;speechSynthesis.speak(u);}
function v3VaniAIResponse(str){const panel=document.querySelector('#v3-ai-response');if(panel)panel.textContent=str;}
async function v3SendAI(e){e.preventDefault();const form=e.target,consent=form.elements.consent?.checked,input=String(form.elements.message.value||'').trim().slice(0,800),endpoint=String(window.MIND_SAGE_CONFIG?.aiEndpoint||'');if(!consent||!input||!/^https:\/\//.test(endpoint))return;
 const button=form.querySelector('button[type="submit"]');button.disabled=true;v3VaniAIResponse(T('Connecting...','যোগাযোগ করা হচ্ছে...'));
 try{const response=await fetch(endpoint,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({message:input,consent:true,adultConfirmed:adult()}),signal:AbortSignal.timeout(30000),credentials:'omit',cache:'no-store'});if(!response.ok)throw new Error('Service unavailable');const data=await response.json();const reply=typeof data.reply==='string'?data.reply.slice(0,2000):'';if(!reply)throw new Error('No reply');v3VaniAIResponse(reply);form.elements.message.value='';}catch(_){v3VaniAIResponse(T('The connected service is unavailable. Please use the local companion or verified support directory.','সংযুক্ত পরিষেবা উপলব্ধ নয়। স্থানীয় সহায়ক বা সহায়তার তালিকা ব্যবহার করুন।'));}finally{button.disabled=false;}}
function v3ExportJournal(){const content='MIND-SAGE · PRIVATE JOURNAL\nPersonal export · '+new Date().toLocaleString('en-IN')+'\n\n'+v3Data.journal.map((j,i)=>`ENTRY ${i+1} | ${j.time} | ${j.tag}\n${j.text}\n`).join('\n---\n\n');downloadBlob(new Blob(['\ufeff'+content],{type:'text/plain;charset=utf-8'}),'Mind-sage-V3-journal-'+dateStamp()+'.txt');}
function v3AddCare(kind){const day=v3Today();if(!v3Data.garden.some(x=>x.date===day&&x.kind===kind)){v3Data.garden.push({date:day,kind});v3Save();}}
function v3Click(e){const el=e.target.closest('[data-v3]');if(!el){if(e.target.closest('[data-action="level"]')){v3Data=V3_DATA_DEFAULT();v3Loaded=false;v3Story=null;}return;}e.preventDefault();e.stopImmediatePropagation();const act=el.dataset.v3,id=el.dataset.id;
 switch(act){
 case 'sky-select':v3Scene=id;render();break;
 case 'sky-save':{const s=V3_SKIES.find(x=>x.id===v3Scene);v3Data.landscape.push({date:new Date().toISOString(),mood:s.mood,label:s.en,id:s.id});v3Save();alert(T('This feeling was saved to your private landscape history.','আপনার অনুভূতিটি ব্যক্তিগত তালিকায় রাখা হয়েছে।'));render();break;}
 case 'garden-care':v3AddCare(id);render();break;
 case 'story-choice':v3Story.choice=Number(el.dataset.index);render();break;
 case 'story-next':if(!v3Story||v3Story.choice===null)return;v3Story.history.push(v3Story.choice);v3Story.index++;v3Story.choice=null;render();break;
 case 'story-restart':if(v3Story){v3Story.index=0;v3Story.choice=null;v3Story.history=[];}render();break;
 case 'story-complete':if(v3Story){v3Data.journeys.push({story:v3Story.id,date:new Date().toISOString()});v3AddCare('reflect');v3Save();go('garden');}break;
 case 'journal-prompt':v3DraftNote=document.querySelector('#v3-journal-note')?.value||v3DraftNote;v3Prompt=id;render();const area=document.querySelector('#v3-journal-note');if(area)area.value=v3DraftNote;break;
 case 'journal-delete':if(confirm(T('Delete this note permanently from this browser?','লেখাটি স্থায়ীভাবে মুছবেন?'))){v3Data.journal=v3Data.journal.filter(x=>x.id!==id);v3Save();render();}break;
 case 'journal-export':v3ExportJournal();break;
 case 'plan-step':{const n=Number(el.dataset.index),plan=v3Data.plan;if(!plan||n<0||n>=plan.duration)return;plan.done=plan.done.includes(n)?plan.done.filter(x=>x!==n):[...plan.done,n].sort((a,b)=>a-b);v3Save();render();break;}
 case 'sound':v3PlaySound(id);break;
 case 'sound-stop':v3StopSound();render();break;
 case 'voice-guide':v3Voice();break;
 case 'voice-stop':if('speechSynthesis' in window)window.speechSynthesis.cancel();break;
 case 'font':v3Prefs.font=['normal','large','xlarge'].includes(id)?id:'normal';v3PrefSave();render();break;
 case 'contrast':v3Prefs.contrast=!v3Prefs.contrast;v3PrefSave();render();break;
 case 'motion':v3Prefs.motion=!v3Prefs.motion;v3PrefSave();render();break;
 case 'install':if(v3DeferredInstall){v3DeferredInstall.prompt();v3DeferredInstall.userChoice.then(()=>{v3DeferredInstall=null;});}else{const m=document.querySelector('#v3-install-msg');if(m)m.textContent=T('Use your browser menu: Install app (desktop) or Add to Home Screen (mobile). Make sure you are viewing the HTTPS GitHub Pages site.','ব্রাউজারের মেনুতে Install app বা Add to Home Screen বেছে নিন।');}break;
 case 'wipe':if(confirm(T('Delete saved journal, garden, plans, journeys, and landscapes from this browser? This cannot be undone.','এই ব্রাউজারের জার্নাল, বাগান, পরিকল্পনা ও অনুভূতির তালিকা মুছবেন?'))){v3Data=V3_DATA_DEFAULT();localStorage.removeItem(V3_STORE_KEY);render();}break;
 }
}
function v3PrefSave(){try{localStorage.setItem(V3_PREF_KEY,JSON.stringify(v3Prefs));}catch(_){}v3ApplyPrefs();}
function v3Submit(e){const id=e.target.id;if(!['v3-journal-form','v3-plan-form','v3-ai-form'].includes(id))return;e.preventDefault();e.stopImmediatePropagation();
 if(id==='v3-journal-form'){const form=e.target,entry=String(form.elements.entry.value||'').trim().slice(0,1500),tag=String(form.elements.tag.value||'reflective');if(!entry)return;v3Data.journal.push({id:String(Date.now())+'-'+Math.random().toString(36).slice(2,8),text:entry,tag,date:v3Today(),time:new Date().toISOString()});v3DraftNote='';v3Save();render();}
 else if(id==='v3-plan-form'){const f=e.target,focus=String(new FormData(f).get('focus')||'study'),duration=Number(new FormData(f).get('duration')||7);if(!V3_FOCUS[focus]||![7,14].includes(duration))return;if(v3Data.plan&&v3Data.plan.done.length&&!confirm(T('Updating your plan will reset the checked days. Continue?','পরিকল্পনা বদলালে চিহ্নিত দিন নতুন করে শুরু হবে। এগোবেন?')))return;v3Data.plan={focus,duration,done:[],startedOn:new Date().toISOString()};v3Save();render();}
 else if(id==='v3-ai-form')v3SendAI(e);
}
function v3Change(e){if(e.target.id==='v3-volume')v3Volume(Number(e.target.value));}
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();v3DeferredInstall=e;});
window.addEventListener('appinstalled',()=>{v3DeferredInstall=null;});
window.addEventListener('beforeunload',()=>{v3StopSound();if('speechSynthesis'in window)speechSynthesis.cancel();});
document.addEventListener('click',v3Click,true);
document.addEventListener('submit',v3Submit,true);
document.addEventListener('input',v3Change,true);
if('serviceWorker'in navigator&&location.protocol==='https:'||('serviceWorker'in navigator&&location.hostname==='localhost')){
  window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js',{scope:'./'}).catch(err=>console.warn('Offline caching unavailable:',err)));
}
if(!location.hash)location.hash='#/home';else navigation();
v3ApplyPrefs();
